const output=document.getElementById("pwd-output"),strength=document.getElementById("strength"),CHARS={upper:"ABCDEFGHIJKLMNOPQRSTUVWXYZ",lower:"abcdefghijklmnopqrstuvwxyz",number:"0123456789",symbol:"!@#$%^&*()_+-=[]{}|;:,.<>?"};function generate(){const t=parseInt(document.getElementById("length").value),e=[];if(document.getElementById("use-upper").checked&&e.push(CHARS.upper),document.getElementById("use-lower").checked&&e.push(CHARS.lower),document.getElementById("use-number").checked&&e.push(CHARS.number),document.getElementById("use-symbol").checked&&e.push(CHARS.symbol),e.length===0){output.textContent=i18n.t("common.select_charset"),output.style.color="#ef4444",strength.textContent="";return}const o=e.join("");let n="";const s=window.crypto||window.msCrypto,r=new Uint32Array(t);s.getRandomValues(r);for(let c=0;c<t;c++)n+=o[r[c]%o.length];output.textContent=n,output.style.color="var(--text)",evaluateStrength(n)}function evaluateStrength(t){let e=0;t.length>=12&&e++,t.length>=20&&e++,/[A-Z]/.test(t)&&e++,/[a-z]/.test(t)&&e++,/[0-9]/.test(t)&&e++,/[^A-Za-z0-9]/.test(t)&&e++;const o=[i18n.t("common.strength_very_weak"),i18n.t("common.strength_weak"),i18n.t("common.strength_normal"),i18n.t("common.strength_strong"),i18n.t("common.strength_very_strong")],n=["#ef4444","#f97316","#eab308","#22c55e","#10b981"],s=Math.min(4,Math.floor(e/1.2));strength.textContent=i18n.t("common.strength_label")+" "+o[s],strength.style.color=n[s]}function downloadResult(){const t=output.textContent;if(!t||t===i18n.t("common.generate_password_placeholder")||t===i18n.t("common.select_charset"))return showToast(i18n.t("common.no_password"));downloadFile(t,"password.txt")}function copyResult(){copyToClipboard(output.textContent).then(()=>showToast(i18n.t("common.copied")))}generate();
